//! Visual Basic 6: `vb6/Azul.bas` (generated by
//! `doc/src/codegen/v2/lang_vb6`).
//!
//! The bindings declare every CSS constructor under its C name
//! (`AzCssProperty_width`, enum members `AzLayoutDisplay_Flex`), but a VB6
//! `Declare` can neither pass a user-defined type ByVal nor return one, and
//! every CSS constructor does both - the generator marks each of them
//! `SKIPPED` and declares a signature VB6 rejects (`As AzCssProperty`
//! result). The out-pointer twins libazul exports for exactly this case
//! (`AzCssProperty_widthByref(AzCssProperty*, AzLayoutWidth*)`) are not
//! declared, so this printer reports each style as not expressible (with
//! the reason) until `lang_vb6` declares them.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Expr, Item, Module, Prim},
    lang::{freebasic::basic_string, item_comments, item_doc, variant_ctor_method, ExprSyntax},
    CodegenBackend, GeneratedFile,
};

/// The VB6 printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Vb6;

impl ExprSyntax for Vb6 {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        text.to_string()
    }

    fn boolean(&self, b: bool) -> String {
        String::from(if b { "True" } else { "False" })
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!("CssStr({})", basic_string(s)))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(format!("Az{class}_{}", snake_to_lower_camel(method)), args, broken)
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("Az{ty}_{variant}")),
            _ => Doc::call(format!("Az{ty}_{}", variant_ctor_method(variant)), args, broken),
        }
    }

    fn strukt(&self, ty: &str, _fields: Vec<(String, Doc)>, _broken: bool) -> Doc {
        Doc::text(format!("New{ty}()"))
    }

    fn vec(&self, ty: &str, _elem: &str, _items: Vec<Doc>, _broken: bool) -> Doc {
        Doc::text(format!("Az{ty}_create()"))
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!("Empty ' not expressible: {what}"))
    }

    fn limitation(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::Int { .. }
            | Expr::Float { .. }
            | Expr::Bool(_)
            | Expr::Variant {
                shape: EnumShape::CLike,
                ..
            } => None,
            _ => Some(REASON.to_string()),
        }
    }
}

const REASON: &str = "a VB6 Declare cannot pass or return a user-defined type by value, so the \
                      bindings skip every CSS constructor (AzCssProperty_width, ...) and do not \
                      declare their out-pointer twins (AzCssProperty_widthByref, ...)";

fn item_fn(item: &Item) -> (bool, String) {
    let name = item.name.upper_camel();
    let mut out = String::new();
    match item_doc(&Vb6, item) {
        Ok(doc) => {
            for line in &item_comments(&Vb6, item) {
                out.push_str(&format!("' {line}\n"));
            }
            out.push_str(&format!(
                "Public Function {name}() As Az{}\n    {name} = {}\nEnd Function\n",
                item.ty,
                render(&doc, "    ", 1)
            ));
            (true, out)
        }
        Err(reason) => {
            // one line for the whole style (not one note per property)
            for line in &item.doc {
                out.push_str(&format!("' {line}\n"));
            }
            out.push_str(&format!("' {name}: not expressible with the VB6 bindings: {reason}\n"));
            (false, out)
        }
    }
}

impl CodegenBackend for Vb6 {
    fn lang(&self) -> &'static str {
        "vb6"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["vb", "visualbasic"]
    }

    fn display_name(&self) -> &'static str {
        "Visual Basic 6"
    }

    fn extension(&self) -> &'static str {
        "bas"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "Attribute VB_Name = \"AzulStyles\"\n' Generated by azul-css codegen (VB6). Do not \
             edit by hand.\nOption Explicit\n",
        );
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item).1);
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let built = m.items.iter().filter(|i| item_fn(i).0).count();
        let main = format!(
            "Attribute VB_Name = \"Main\"\n' Add target/codegen/vb6/Azul.bas, AzulStyles.bas and \
             this module to a Standard EXE project.\nOption Explicit\n\nSub Main()\n    MsgBox \
             \"styles expressible with these bindings: {built}\"\nEnd Sub\n"
        );
        vec![
            GeneratedFile {
                path: "AzulStyles.bas".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "Main.bas".to_string(),
                contents: main,
            },
        ]
    }
}
